from fractions import Fraction as F
import json
rows=[('A',13,(1,0,0,0)),('A',3,(0,0,0,1)),('B',9,(1,0,1,0)),('B',5,(0,0,1,1)),('C',5,(1,1,1,0)),('C',8,(0,0,1,0)),('D',6,(1,0,0,0)),('D',5,(0,0,1,1))]
names='TUVW'; modes='ABCD'
loss=[[0,11,6,16],[22,0,20,8],[16,23,0,7],[18,11,20,0]]
cost=[F('1.8'),F('1.5'),F('1.2'),F('.8')]
def stop(ids):
    mass=sum(rows[i][1] for i in ids)
    return min((F(sum(rows[i][1]*loss[a][modes.index(rows[i][0])] for i in ids),mass),modes[a]) for a in range(4))
def testval(ids,t,remaining):
    mass=sum(rows[i][1] for i in ids)
    val=cost[t]
    for v in (0,1):
        sub=tuple(i for i in ids if rows[i][2][t]==v)
        if sub:
            val+=F(sum(rows[i][1] for i in sub),mass)*best(sub,remaining)[0]
    return val
def best(ids,remaining):
    choices=[stop(ids)]
    for t in remaining:
        choices.append((testval(ids,t,()),names[t]))
    return min(choices)
ids=tuple(range(8))
vals={'STOP':float(stop(ids)[0])}
for t in range(4): vals[names[t]]=float(testval(ids,t,tuple(k for k in range(4) if k!=t)))
first=min(vals,key=vals.get)
assert first=='V'
t=names.index(first)
nxt={str(v):best(tuple(i for i in ids if rows[i][2][t]==v),tuple(k for k in range(4) if k!=t))[1] for v in (0,1)}
# Independent check: enumerate all fixed first-test branch policies, using weighted raw repair totals.
def rawstop(sub): return min(sum(rows[i][1]*loss[a][modes.index(rows[i][0])] for i in sub) for a in range(4))
check={}
for t in range(4):
    total=cost[t]*54
    for v in (0,1):
        sub=[i for i in ids if rows[i][2][t]==v]
        opts=[F(rawstop(sub))]
        for s in range(4):
            if s!=t:
                opts.append(cost[s]*sum(rows[i][1] for i in sub)+sum(rawstop([i for i in sub if rows[i][2][s]==b]) for b in (0,1)))
        total+=min(opts)
    check[names[t]]=float(total/54)
assert all(abs(vals[k]-check[k])<1e-10 for k in check)
print(json.dumps({'first':first,'first_losses':vals,'next':nxt}))

