import json
from fractions import Fraction as F
# A repeated display of the same reading supplies no additional evidence.
r=[('A',3,(0,0,0)),('B',5,(0,0,1)),('D',5,(0,0,1))]
M='ABCD'; tests='TUV'; costs=[F('1.8'),F('1.5'),F('7.2')]
L=[[0,11,6,16],[22,0,20,8],[16,23,0,7],[18,11,20,0]]
def repairs(s):
 mass=sum(r[i][1] for i in s)
 return {a:F(sum(r[i][1]*L[j][M.index(r[i][0])] for i in s),mass) for j,a in enumerate(M)}
s=list(range(3)); losses=repairs(s)
for t in range(3):
 val=costs[t]
 for b in (0,1):
  q=[i for i in s if r[i][2][t]==b]
  if q:val+=F(sum(r[i][1] for i in q),13)*min(repairs(q).values())
 losses[tests[t]]=val
a=min(losses,key=losses.get); after={}
if a in tests:
 t=tests.index(a)
 for b in (0,1):
  q=[i for i in s if r[i][2][t]==b]
  after[str(b)]=min(repairs(q),key=repairs(q).get) if q else 'IMPOSSIBLE'
assert losses['B']==F(106,13)
assert losses['V']==F('7.2')+F(40,13)
assert a=='B'
print(json.dumps({'posterior':{m:float(F(sum(w for mode,w,_ in r if mode==m),13)) for m in M},'remaining_losses':{k:float(v) for k,v in losses.items()},'action':a,'repair_after':after}))

